<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\Holder\TenantLoginProviderPrivateKeyAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantLoginProviderPrivateKeyAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TenantLoginProviderPrivateKeyAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getPrivateKey returns null on a freshly created holder.
     */
    public function testPrivateKeyNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderPrivateKeyAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isPrivateKeyAssigned());
        $this->assertNull($holder->getPrivateKey());
    }
}
class ImplWithTenantLoginProviderPrivateKeyAttributeHolderUnitTest
{
    use TenantLoginProviderPrivateKeyAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedPrivateKeyRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultPrivateKey();
    }
}
